//! Persisted server profiles. These contain NO secrets — passwords live in the
//! OS credential store (see `secrets.rs`), keyed by the profile `id`.

use crate::error::AppResult;
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

fn default_true() -> bool {
    true
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ServerProfile {
    /// Stable unique id (generated by the UI, e.g. a UUID).
    pub id: String,
    /// Human-friendly name shown in the server picker.
    pub name: String,
    /// Base URL including scheme and port, e.g. `https://nvr.local:8971`.
    pub base_url: String,
    /// Username used for `/api/login` (empty when auth is disabled).
    #[serde(default)]
    pub username: String,
    /// Accept self-signed / invalid TLS certificates for this server.
    #[serde(default)]
    pub allow_insecure: bool,
    /// Whether this server requires authentication (Frigate 0.14+ on :8971).
    #[serde(default = "default_true")]
    pub requires_auth: bool,
}

fn profiles_path(dir: &Path) -> PathBuf {
    dir.join("profiles.json")
}

pub fn load(dir: &Path) -> AppResult<Vec<ServerProfile>> {
    let path = profiles_path(dir);
    if !path.exists() {
        return Ok(Vec::new());
    }
    let data = std::fs::read_to_string(&path)?;
    if data.trim().is_empty() {
        return Ok(Vec::new());
    }
    Ok(serde_json::from_str(&data)?)
}

pub fn save(dir: &Path, profiles: &[ServerProfile]) -> AppResult<()> {
    std::fs::create_dir_all(dir)?;
    let path = profiles_path(dir);
    std::fs::write(path, serde_json::to_string_pretty(profiles)?)?;
    Ok(())
}

/// Insert or update a profile (matched by id), then persist the list.
pub fn upsert(dir: &Path, profile: ServerProfile) -> AppResult<Vec<ServerProfile>> {
    let mut profiles = load(dir)?;
    match profiles.iter_mut().find(|p| p.id == profile.id) {
        Some(existing) => *existing = profile,
        None => profiles.push(profile),
    }
    save(dir, &profiles)?;
    Ok(profiles)
}

/// Remove a profile by id, then persist the list.
pub fn remove(dir: &Path, id: &str) -> AppResult<Vec<ServerProfile>> {
    let mut profiles = load(dir)?;
    profiles.retain(|p| p.id != id);
    save(dir, &profiles)?;
    Ok(profiles)
}

pub fn find(dir: &Path, id: &str) -> AppResult<Option<ServerProfile>> {
    Ok(load(dir)?.into_iter().find(|p| p.id == id))
}
